type Props={warmup?:boolean;state:Data;run(method:string,params?:Data):Promise<any>;act(method:string,params?:Data):void;open(kind:string,data?:Data):void;notify(text:string):void}
// Draw each page in the actual viewport before enabling interaction. Nested
// translucent previews compile different GPU passes from the presented scene.
// Only one temporary page exists at a time and no hidden pages are retained.
function usePageMaterials(enabled:boolean,root:{current:HTMLElement|null}){
 const [index,setIndex]=useState(0),active=index<pages.length
 useEffect(()=>{
  if(!enabled||!active)return
  let live=true,animation:Animation|undefined
  void(async()=>{
   await document.fonts.ready;await afterPaint()
   await Promise.all([waitGlassMaps(),waitPanelMaps()]);await afterPaint()
   if(!live||!root.current)return
   animation=root.current.animate([{opacity:.38},{opacity:.9999}],{duration:180,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'})
   await afterPaint();await window.cinema.window('prime').catch(()=>{})
   if(!live)return
   animation.finish();await afterPaint();await window.cinema.window('prime').catch(()=>{})
   animation.cancel();if(live)setIndex(i=>i+1)
  })()
  return()=>{live=false;animation?.cancel()}
 },[enabled,index])
 useEffect(()=>{let live=true;if(!active)void afterPaint().then(()=>{if(live)finishStartupWarmup('page-materials')});return()=>{live=false}},[active])
 return active?pages[index][0]:null
}
