function useBrowseHistory(key:string){const [directory,setDirectory]=useDraft('directory.'+key,''),history=useRef([directory]),cursor=useRef(0)
 const visit=(value:string)=>{if(value===history.current[cursor.current])return;history.current=history.current.slice(0,cursor.current+1).concat(value);cursor.current++;setDirectory(value)}
 useEffect(()=>{if(key!=='media')return;const reset=()=>{history.current=[''];cursor.current=0;setDirectory('')};window.addEventListener('cinema:libraryRemoved',reset);return()=>window.removeEventListener('cinema:libraryRemoved',reset)},[key])
 useEffect(()=>{const move=(forward:boolean)=>{const next=cursor.current+(forward?1:-1);if(next>=0&&next<history.current.length){cursor.current=next;setDirectory(history.current[next])}};const mouse=(e:MouseEvent)=>{if(e.button===3||e.button===4){e.preventDefault();if(e.type!=='auxclick')move(e.button===4)}};const key=(e:KeyboardEvent)=>{if(e.altKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(e.key==='ArrowRight')}};window.addEventListener('mouseup',mouse);window.addEventListener('auxclick',mouse);window.addEventListener('keydown',key);return()=>{window.removeEventListener('mouseup',mouse);window.removeEventListener('auxclick',mouse);window.removeEventListener('keydown',key)}},[])
 return {directory,visit}
}
